<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<scroll-view scroll-y="true" class="scroll" @scrolltolower="loadMore">
			<view class="money-items" v-if="lists.length>0">
				<view class="money-item" v-for="(item,index) in lists" :key="index">
					<view class="left">
						<view class="title">支付方式:{{item.pay_name}}</view>
						<view class="time">{{item.add_time}}</view>
					</view>
					<view class="right">
						<view class="money">{{item.order_amount}}</view>
						<view class="status">状态:{{item.status_text}}</view>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<view class="empty-container" v-else>
				<u-empty text="暂无充值记录" :icon="emptyIcon" />
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				pageIndex: 1,
				pageSize: 10,
			}
		},
		onLoad(e) {
			_this = this;
			_this.get_chongzhi_jilu()
		},
		methods: {
			loadMore(){
				if(_this.hasMore){
					_this.pageIndex++
					_this.get_chongzhi_jilu()
				}
			},
			async get_chongzhi_jilu(){
				const params = {
					pageIndex: _this.pageIndex,
					pageSize: _this.pageSize,
				}
				const data = await _this.$post('port/chongzhi_list', params)
				if(data.code==200){
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length >= _this.pageSize
				}else{
					_this.hasMore = false
				}
				if (_this.load) {
					_this.load = false
				}
			}
		}
	}
</script>

